def text(x):
    if x is None:
        return ''
    if isinstance(x, (list, tuple, set)):
        return ' '.join([text(i) for i in x])
    if isinstance(x, dict):
        return ' '.join([text(k) + ' ' + text(v) for k, v in x.items()])
    return str(x).lower()

def needverb(tt):
    if 'cool' in tt:
        return 'cool'
    if 'heat' in tt:
        return 'heat'
    if 'clean' in tt:
        return 'clean'
    return ''

def hook(ctx, nb):
    tt = text(val(ctx, 'task.task_type', ''))
    target = text(val(ctx, 'task.target_type', ''))
    dest = text(val(ctx, 'task.destination_type', ''))
    verb = needverb(tt)
    if not verb:
        nb['transformed'] = True
    act = text(val(ctx, 'action.final_action', val(ctx, 'action.normalized', val(ctx, 'action.raw', ''))))
    obs = text(ctx.get('observation', ''))
    inv = text(val(ctx, 'world.inventory', ''))
    if target and act.startswith('take ') and target in act and 'pick up' in obs:
        nb['target_taken'] = True
    if target and act.startswith('put ') and target in act and 'you put' in obs:
        nb['target_put'] = True
    if target and verb and target in act and act.startswith(verb + ' ') and 'nothing happens' not in obs:
        nb['transformed'] = True
    pc = val(ctx, 'world.placed_count', None)
    if isinstance(pc, int) and pc > nb.get('placed_count', 0):
        nb['placed_count'] = pc
    locs = val(ctx, 'world.placed_locations', None)
    if isinstance(locs, (list, tuple, set)):
        nb['placed_locations'] = [text(x) for x in locs]
    elif locs:
        nb['placed_locations'].append(text(locs))
    has_target = bool(target and target in inv)
    has_any = bool(inv and 'nothing' not in inv and 'not carrying' not in inv and 'empty' not in inv)
    take_here = bool(target and any(a.startswith('take ') and target in a for a in ctx.get('admissible', [])))
    put_here = bool(target and dest and any(a.startswith('put ') and target in a and dest in a for a in ctx.get('admissible', [])))
    if has_any and target and not has_target:
        stage = 'wrong_inventory'
    elif has_target and verb and not nb.get('transformed'):
        stage = 'transform'
    elif has_target and dest and not put_here:
        stage = 'go_destination'
    elif has_target and dest and put_here:
        stage = 'put_target'
    elif take_here or val(ctx, 'world.target_found', False) or val(ctx, 'world.target_location', ''):
        stage = 'take_target'
    else:
        stage = 'find_target'
    nb['stage'] = stage
    nb['target_type'] = target
    nb['destination_type'] = dest
    nb['task_type'] = tt
    nb['transform_verb'] = verb
    return None

