def hook(ctx, nb):
    stage = nb.get('stage', '')
    target = nb.get('target_type') or text(val(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(val(ctx, 'task.destination_type', ''))
    verb = nb.get('transform_verb') or needverb(val(ctx, 'task.task_type', ''))
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'Inventory does not match the requested target type. Do not place a wrong item at the destination; recover by setting it aside if needed and searching for the target.'
    elif stage == 'take_target' and target:
        msg = 'A requested ' + target + ' is available here. Take the target now instead of continuing to search other containers.'
    elif stage == 'transform' and target and verb:
        msg = 'You are carrying the ' + target + '. Use the required ' + verb + ' action before placing it; do not put it at the destination yet.'
    elif stage == 'go_destination' and target and dest:
        msg = 'Carry the ' + target + ' to a ' + dest + ' and put it there. Do not place it in a different receptacle.'
    elif stage == 'put_target' and target and dest:
        msg = 'You are at the correct ' + dest + ' with the ' + target + '. Use the put action for this destination and do not take the item back.'
    elif stage == 'find_target' and target and (val(ctx, 'predicates.same_action_repeated', False) or val(ctx, 'predicates.same_observation_repeated', False) or val(ctx, 'predicates.remaining_steps_low', False)):
        msg = 'Search unopened or unvisited containers for the requested ' + target + ', but stop searching as soon as a matching take action appears.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

