    return ''

def hook(ctx, nb):
    tt = text(val(ctx, 'task.task_type', ''))
    target = text(val(ctx, 'task.target_type', nb.get('target_type', '')))
    dest = text(val(ctx, 'task.destination_type', nb.get('destination_type', '')))
    verb = nb.get('transform_verb') or needverb(tt)
    act = text(val(ctx, 'action.final_action', val(ctx, 'action.normalized', val(ctx, 'action.raw', ''))))
    if not target or not act:
        return None
    if nb.get('stage') == 'wrong_inventory' and act.startswith('put ') and target not in act:
        return {'kind': 'block_and_prompt', 'message': 'This is not the requested target type. Do not place a wrong item at the destination; recover by finding the target instead.'}
    if verb and not nb.get('transformed') and target in act and act.startswith('put '):
        return {'kind': 'block_and_prompt', 'message': 'Do not place the target yet. First use the required ' + verb + ' action, then go to the destination.'}
    if nb.get('stage') == 'transform' and target in act and act.startswith('put '):
        return {'kind': 'block_and_prompt', 'message': 'The required transform step is still pending. Use the ' + verb + ' action before putting the item anywhere.'}
    if nb.get('stage') == 'put_target' and target in act and dest and dest not in act and act.startswith('put '):
        return {'kind': 'block_and_prompt', 'message': 'This is not the requested destination type. Carry the target to a ' + dest + ' and put it there.'}
    if nb.get('stage') == 'put_target' and target in act and dest and dest in act and act.startswith('take '):
        return {'kind': 'block_and_prompt', 'message': 'Do not take the target back after placing it at the correct destination. The subgoal is complete.'}
    if 'two' in tt and target in act and act.startswith('take '):
        locs = nb.get('placed_locations') or []
        for loc in locs:
            if loc and loc in act:
                return {'kind': 'block_and_prompt', 'message': 'Do not take back an item already placed for the two-object task. Find another target of the same type.'}
    return None
